package com.javatpoint.servlets;
import java.io.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import com.javatpoint.beans.IssueBookBean;import com.javatpoint.dao.BookDao;import com.javatpoint.util.*;
@WebServlet("/ViewIssuedBook") public class ViewIssuedBook extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{if(!AuthUtil.requireLibrarian(q,r))return;r.setContentType("text/html;charset=UTF-8");PrintWriter o=r.getWriter();o.print("<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Issued books | eLibrary</title><link rel='stylesheet' href='bootstrap.min.css'><link rel='stylesheet' href='app.css'></head><body>");q.getRequestDispatcher("navlibrarian.html").include(q,r);o.print("<div class='page'><div class='hero'><h1>Circulation</h1><p>Track active and completed book issues.</p></div><div class='card table-card'><table class='table table-hover'><thead><tr><th>Call no.</th><th>Student ID</th><th>Student</th><th>Mobile</th><th>Issued</th><th>Status</th></tr></thead><tbody>");for(IssueBookBean b:BookDao.viewIssuedBooks()){String status=HtmlUtil.e(b.getReturnstatus());String cls="yes".equalsIgnoreCase(status)?"status-yes":"status-no";o.print("<tr><td>"+HtmlUtil.e(b.getCallno())+"</td><td>"+HtmlUtil.e(b.getStudentid())+"</td><td>"+HtmlUtil.e(b.getStudentname())+"</td><td>"+b.getStudentmobile()+"</td><td>"+HtmlUtil.e(String.valueOf(b.getIssueddate()))+"</td><td><span class='badge-status "+cls+"'>"+status+"</span></td></tr>");}o.print("</tbody></table></div></div></body></html>");}}
